19	  const { spaceId, environment, previewAccessToken, accessToken } = getContentfulConfig() ?? {};
20	  const resolvedToken = previewAccessToken || accessToken;
21	
22	  const client = useMemo(
23	    () => {
24	      if (!spaceId || !resolvedToken) return null;
25	      return createClient({
26	        space: spaceId,
27	        environment,
28	        // preview token → shows draft content (local/staging); delivery token → CDN-cached published content (production)
